SAMPLING_REQUIREMENTS: Dict[str, Dict[str, Any]] = {'vibration': {'min_hz': 51200.0, 'warn_hz': 102400.0, 'msg': 'High-frequency gear-mesh harmonics >10 kHz require 51.2-102.4 kSPS. Bearing defect/envelope/demodulation band 1-25 kHz; structural resonance 5-25 kHz. Broadband 10 Hz-10 kHz minimum; 25.6 kSPS adequate for envelope to ~10 kHz, but HF gear-mesh needs the higher rate. 2-second minimum capture for FFT resolution (df<=0.5 Hz to resolve sidebands).'}, 'acoustic_emission': {'min_hz': 2000000.0, 'warn_hz': 5000000.0, 'msg': 'AE frequency range 20 kHz-1 MHz (wideband sensors 200-1000 kHz); sampling 2-5 MSps minimum (2x highest frequency per Nyquist). Burst-capture triggered mode for incipient crack detection at 100-500 kHz.'}, 'current': {'min_hz': 10000.0, 'warn_hz': 25000.0, 'msg': 'MCSA needs 10-25 kHz per channel with long FFT window (20-60 s for <0.01 Hz resolution) to resolve broken-rotor-bar sidebands at f0+/-2sf and bearing-fault sidebands 10-20 dB below fundamental; high Fs gives the dBc separation to see -50 dBc sidebands.'}, 'position': {'min_hz': 20000.0, 'warn_hz': 40000.0, 'msg': 'Proximity/eddy-current probes 20-40 kSPS per channel (2 channels per fluid-film bearing, 90deg apart); LVDT/servo valve bandwidth 100 Hz+ but eddy-current orbit waveform needs kHz-class. Dynamic response DC to ~10 kHz covers all sub-synchronous and synchronous shaft motion.'}, 'pressure': {'min_hz': 100.0, 'warn_hz': 1000.0, 'msg': 'AGC servo cylinders correct in milliseconds; compressor surge 0.6-2.5 Hz pulsation and reciprocating P-V cylinder waveforms need crank-angle resolution. 1-100 Hz dynamic; lube-starvation acute events need 1-5 s windows; >=100 Hz to resolve per-revolution transients.'}, 'force_torque': {'min_hz': 100.0, 'warn_hz': 1000.0, 'msg': 'Caster oscillator friction spikes at negative-strip period; rolling-force ripple at once-per-roll-rev; chatter detection. Need to resolve per-oscillation/per-revolution events, so >=100 Hz.'}, 'level': {'min_hz': 10.0, 'warn_hz': 100.0, 'msg': 'Caster mold level oscillation (breakout precursor) is a frequency signature; safety-critical breakout system fed direct via IPC at <100 ms latency. >=10 Hz to resolve level-wave dynamics.'}, 'flow': {'min_hz': 1.0, 'warn_hz': 10.0, 'msg': '1-10 Hz typical; Coriolis can reach 100+ Hz. Flow deviations trended against 30-day rolling baseline +/-2sigma; averaging smooths turbulence.'}, 'temperature': {'min_hz': 1.0, 'warn_hz': 10.0, 'msg': 'Slow thermal physics; 1 Hz continuous SCADA sufficient. Rate-of-change rules (>2C/h bearing, >5C/15min) need at least 1 sample/minute for reliable trend slope; furnace zones acquired slower (0.01-0.1 Hz).'}, 'power': {'min_hz': 1.0, 'warn_hz': 10.0, 'msg': 'PF/THD/DC-link ripple/shaft-voltage trending; 1-10 Hz for slow electrical-health drift, 10 ms for power-quality/PD analyzers.'}, 'speed': {'min_hz': 1.0, 'warn_hz': 10.0, 'msg': 'High-rate pulse counting at 1 kHz; computed velocity every 10-100 ms; 1 Hz trend to historian. Keyphasor 1 pulse/rev for synchronous averaging.'}, 'oil_quality': {'min_hz': 0.001, 'warn_hz': 0.1, 'msg': 'Slow-evolving parameter; online particle counters sample every 10-1000 s (1/min for critical systems); route-based lab analysis every 500-1000 operating hours.'}}

