QUALITY_RULES: List[Dict[str, Any]] = [{'rule_id': 'VIB_STEADY_STATE_GATE', 'check': 'Only evaluate vibration against ISO zones during steady-state window (RPM within +/-2% of rated, load >80%); gate/suppress alarms during start/stop transients', 'severity': 'warn', 'applies_to': 'vibration', 'rationale': 'Transient events during start/stop produce non-representative readings; ISO zones apply only to steady-state operation.'}, {'rule_id': 'VIB_LOAD_SPEED_NORMALIZE', 'check': 'Do not compare vibration/AE measurements taken at different loads or speeds; use load-normalized and speed-normalized baselines; ISO 10816-3 Criterion II change-rate (>25% of Zone B upper) evaluated at matched conditions', 'severity': 'warn', 'applies_to': 'vibration', 'rationale': 'Load variation alone changes amplitude; comparing across operating points generates false alarms.'}, {'rule_id': 'VIB_BACKGROUND_SUBTRACT', 'check': 'If machine-off background vibration exceeds 25% of machine-on level, subtract or flag (ISO 10816-3 sec 3.4)', 'severity': 'warn', 'applies_to': 'vibration', 'rationale': 'Background vibration from cranes/conveyors/adjacent machines contaminates the measurement.'}, {'rule_id': 'VIB_EMI_NOISE_5_20KHZ', 'check': 'High-frequency noise at 5-20 kHz with no mechanical correlate indicates loose accelerometer mount (check torque 2-5 Nm for M6) or VFD/EMI pickup, not a fault; require shielded cable + single-point ground', 'severity': 'warn', 'applies_to': 'vibration', 'rationale': 'Loose mounting and VFD electrical noise are top false-alarm sources.'}, {'rule_id': 'VIB_NONNEGATIVE', 'check': 'vibration RMS velocity must be >=0 and <=50 mm/s; negative or implausibly high indicates transducer/cabling fault not real machine state', 'severity': 'error', 'applies_to': 'vibration', 'rationale': 'ISO 10816 danger zone is ~7-11 mm/s; readings far above 50 mm/s indicate sensor fault.'}, {'rule_id': 'MULTI_SENSOR_FUSION', 'check': 'Require corroboration across vibration + temperature + AE before escalating; single-sensor false-positive rate is 35-40%, multi-sensor fusion drops it below 8%', 'severity': 'info', 'applies_to': 'bearing', 'rationale': 'Multi-sensor fusion dramatically reduces false positives in bearing/gearbox PdM.'}, {'rule_id': 'ALARM_PERSISTENCE', 'check': 'Require alarm persistence across 3 consecutive measurement intervals before escalating', 'severity': 'warn', 'applies_to': 'bearing', 'rationale': 'Single-interval spikes are often noise; persistence filters transient false alarms.'}, {'rule_id': 'KURTOSIS_PREFILTER', 'check': 'Pre-filter to high-frequency band before computing kurtosis/crest factor; large low-frequency signals (imbalance, misalignment) mask impulsive bearing signals', 'severity': 'warn', 'applies_to': 'vibration', 'rationale': 'Kurtosis/crest factor on unfiltered signal misses bearing impulses hidden under dominant imbalance/misalignment energy.'}, {'rule_id': 'KURTOSIS_STAGE4_PARADOX', 'check': 'A kurtosis drop back toward 3 with simultaneously high broadband RMS indicates Stage-4 near-failure (random broadband damage), NOT recovery', 'severity': 'critical', 'applies_to': 'bearing', 'rationale': 'At Stage 4 kurtosis paradoxically falls as discrete impulses merge into noise floor; reading kurtosis normal as healthy would miss imminent seizure.'}, {'rule_id': 'PROX_GLITCH_FILTER', 'check': 'Apply glitch/synchronous-notch filter for proximity-probe spikes caused by keyway, oil hole, or surface irregularity passing under the probe', 'severity': 'warn', 'applies_to': 'position', 'rationale': 'Target surface defects produce false high-frequency spikes (mechanical/electrical runout) that must be tracked out, not alarmed.'}, {'rule_id': 'TEMP_TREND_NOT_ABSOLUTE', 'check': 'Alarm bearing temperature on +20degC-above-baseline trend, not only on absolute threshold; do not alarm on gradual IEPE/ambient drift without trend context', 'severity': 'warn', 'applies_to': 'temperature', 'rationale': 'Baseline-relative trending catches developing faults earlier than fixed thresholds and avoids ambient-drift false alarms.'}, {'rule_id': 'TEMP_RATE_RULE', 'check': 'Apply rate-of-change: bearing temp rise >2C/hour sustained (or >15C/hr, >5C/15min) = alarm regardless of absolute value; >10C above running baseline = caution', 'severity': 'high', 'applies_to': 'temperature', 'rationale': 'Absolute-threshold-only logic misses fast-developing lube-starvation events; rate captures them earlier.'}, {'rule_id': 'AE_BASELINE_DEVIATION', 'check': 'AE thresholds must be deviation-based against a per-asset commissioning baseline established at rated speed and load, never absolute; suppress AE alarms during cooling-water/steam-jet process noise', 'severity': 'warn', 'applies_to': 'acoustic_emission', 'rationale': 'AE baselines are highly plant- and asset-specific (EHD film background); process noise causes false bursts unless load-normalized and process-state-gated.'}, {'rule_id': 'AE_NO_SOLO_TRIP', 'check': 'Do not schedule shutdown/trip on acoustic_emission alone; require AE + vibration frequency confirmation (BPFO/BPFI/GMF) before trip on bearings/gears', 'severity': 'high', 'applies_to': 'acoustic_emission', 'rationale': 'AE fires in Stage 1 (4-8 wk early) with no vibration change; AE alone causes premature shutdowns.'}, {'rule_id': 'SLOW_SPEED_USE_AE', 'check': 'For bearings below ~100 RPM (caster withdrawal rolls 10-30 RPM, ladle car wheels, walking-beam hearth) use AE RMS trending; conventional vibration is ineffective as defect frequencies fall below 1 Hz', 'severity': 'info', 'applies_to': 'acoustic_emission', 'rationale': 'Slow-speed bearing defect frequencies are sub-1 Hz; AE from asperity contact is the only reliable PdM technique.'}, {'rule_id': 'OIL_TANK_PARTICLE_DEDUP', 'check': 'Treat oil-debris rate-of-change as primary, not just absolute count; a rapid rate-of-change at any absolute level warrants alarm; ferrous index doubling in 72h = acute wear', 'severity': 'warn', 'applies_to': 'oil_quality', 'rationale': 'Spall area growth correlates to ferrous particle rate-of-change; rapid increase precedes catastrophic failure before absolute thresholds are crossed.'}, {'rule_id': 'OIL_TREND_OVER_LIMIT', 'check': 'Use trend rate, not fixed limits, for wear metals and ISO code; an ISO 4406 jump of +2 code steps (4x particles) is action-level even if absolute code is nominal; require new-oil baseline at oil-fill + 50h run before trending', 'severity': 'high', 'applies_to': 'oil_quality', 'rationale': 'Fixed wear-metal limits inadequate; Fe>500 ppm may be normal in one gearbox and alarming in a servo circuit.'}, {'rule_id': 'OIL_SAMPLE_VALIDITY', 'check': 'Reject oil-analysis samples taken at cold start or from contaminated/unlabelled bottles; under-read wear metals settle out and spurious particle spikes occur', 'severity': 'medium', 'applies_to': 'oil_quality', 'rationale': 'Sample timing and bottle contamination produce both false-negatives (settled particles) and false-positives (residual particles).'}, {'rule_id': 'OIL_OXIDATION_VS_CONTAM', 'check': 'If viscosity + acid number + water ppm + particle count all degrade together -> oxidation root cause; if only particle count spikes without viscosity change -> external contamination (not oxidation)', 'severity': 'medium', 'applies_to': 'oil_quality', 'rationale': 'Pattern of co-degradation distinguishes oil oxidation from external contamination.'}, {'rule_id': 'WATER_IN_OIL_THRESHOLD', 'check': 'Flag water-in-oil >200 ppm as alarm, >500 ppm as critical (milky free water requiring drain/flush)', 'severity': 'warn', 'applies_to': 'oil_quality', 'rationale': 'Water causes additive depletion, hydrolysis, servo body corrosion, bearing corrosion within 2 weeks.'}, {'rule_id': 'OIL_CLEANLINESS_STEP', 'check': 'Flag ISO 4406 cleanliness degrading >=1 code step from baseline; each step = 2x particle concentration; AGC servo target ISO 16/14/11', 'severity': 'warn', 'applies_to': 'oil_quality', 'rationale': 'Degradation to 18/16/13 drives 4-6x higher servo valve replacement rate; act before servo silting symptoms appear.'}, {'rule_id': 'MCSA_CONFIRMATORY_ONLY', 'check': 'Treat MCSA-derived bearing/gear fault flags as confirmatory, not primary; low SNR (sidebands 10-20 dB below fundamental) and load/electrical noise reduce reliability', 'severity': 'info', 'applies_to': 'current', 'rationale': 'MCSA is non-invasive but lower-sensitivity; should corroborate vibration/AE rather than trigger action alone.'}, {'rule_id': 'MCSA_LOAD_GATE', 'check': 'MCSA broken-rotor-bar diagnosis only valid when motor load >60% FLA; at <30% load the 2sf sidebands sit too close to the fundamental to resolve', 'severity': 'high', 'applies_to': 'current', 'rationale': 'Light load = small slip; sidebands merge with fundamental, producing false-negative on broken bars.'}, {'rule_id': 'MCSA_VFD_MASK', 'check': 'Flag MCSA spectra from VFD-fed motors as low-confidence; PWM carrier harmonics dominate and bury broken-bar sidebands; corroborate with vibration before alarming', 'severity': 'medium', 'applies_to': 'current', 'rationale': 'MCSA is less effective on VFDs.'}, {'rule_id': 'PHASE_IMBALANCE_THERMAL', 'check': 'When phase-current imbalance >5%, add ~25C per 1% above 5% to expected winding temperature (NEMA); reconcile current-imbalance and winding-RTD readings', 'severity': 'high', 'applies_to': 'current', 'rationale': 'NEMA MG-1 rule; imbalance-driven heating must be cross-checked against RTD to confirm stator fault vs sensor error.'}, {'rule_id': 'EDM_NOT_BEARING_FREQ', 'check': 'Broadband HF noise-floor elevation (3-6 dB) NOT aligned to BPFO/BPFI/BSF/FTF, with grey/black metallic grease, indicates VFD electrical erosion (fluting), not mechanical race fault', 'severity': 'info', 'applies_to': 'bearing', 'rationale': 'EDM fluting is misdiagnosed as mechanical fault; its non-synchronous broadband signature points to shaft-grounding remedy.'}, {'rule_id': 'SHAFT_VOLTAGE_VFD_ONLY', 'check': 'Apply shaft-voltage EDM thresholds (>5V caution, >15V action) only to VFD-driven motors; correlate with vibration noise-floor rise across 2-10 kHz', 'severity': 'medium', 'applies_to': 'power', 'rationale': 'EDM bearing erosion is a VFD-specific failure mode; shaft voltage on DOL motors is not the same hazard.'}, {'rule_id': 'BEARING_2OF3', 'check': 'For bearing trip decisions require at least 2 of 3 corroborating sensors: AE RMS rise, envelope BPFO/BPFI amplitude rise, bearing temperature rate-of-change', 'severity': 'high', 'applies_to': 'bearing', 'rationale': 'Single-sensor bearing trips have high false-alarm rate; 2-of-3 voting is the documented corroboration rule.'}, {'rule_id': 'TEMP_LAGGING', 'check': 'Treat temperature as lagging/confirmatory only; never wait for temperature to alarm before acting on a bearing fault; prefer rate-of-change over absolute value', 'severity': 'high', 'applies_to': 'temperature', 'rationale': 'Temperature is Stage 3-4; AE and vibration lead it by weeks.'}, {'rule_id': 'CASTER_BREAKOUT_3SENSOR', 'check': 'Caster mould breakout alarm MUST require all 3 to agree: thermocouple V-pattern cold spot + oscillator friction force spike + mould level oscillation. Do not alarm on any single sensor', 'severity': 'high', 'applies_to': 'caster', 'rationale': 'Single-sensor mould breakout detection has >40% false-alarm rate.'}, {'rule_id': 'GEARBOX_OIL_CONFIRM', 'check': 'Confirm gearbox mechanical wear by oil ferrous ppm / PQ Index rise before attributing vibration GMF-sideband changes to gear wear (vs electrical/measurement noise artifact)', 'severity': 'medium', 'applies_to': 'gearbox', 'rationale': 'Oil debris distinguishes real mechanical wear from electrical noise in the vibration spectrum.'}, {'rule_id': 'MOTOR_3SENSOR_WINDING', 'check': 'Before condemning a motor winding, require MCSA + vibration + temperature (and PI for insulation vs rotor discrimination) to agree', 'severity': 'high', 'applies_to': 'motor', 'rationale': 'All three indicators must agree before condemning a winding; PI separates winding fault from rotor fault.'}, {'rule_id': 'PUMP_CURVE_GROUNDTRUTH', 'check': 'Use flow-vs-head curve deviation as ground truth for pump faults; cavitation requires pressure fluctuation + AE + suction pressure drop all present', 'severity': 'medium', 'applies_to': 'pump', 'rationale': 'Operating-point deviation from the pump curve is the definitive confirmation; cavitation is a 3-sensor pattern.'}, {'rule_id': 'DRY_RUN_MULTI_SENSOR', 'check': 'Flag pump dry-run only when motor current drop AND discharge pressure drop AND low suction coincide, not single-sensor', 'severity': 'warn', 'applies_to': 'pump', 'rationale': 'Dry-run signature is simultaneous current+discharge+suction collapse; irreversible damage in 2-5 min so correlation must be fast.'}, {'rule_id': 'HYDRAULIC_SENSOR_FUSION', 'check': 'Require multivariate correlation (ISO cleanliness + servo lag + filter dP slope + oil temp + case drain temp/flow + servo position error) before raising hydraulic failure alarm; contamination should degrade all in parallel', 'severity': 'warn', 'applies_to': 'hydraulic', 'rationale': 'Pressure spikes from process demand cause many false positives; a lone ISO-code step without case-drain/position change suggests sampling error.'}, {'rule_id': 'FILTER_DP_COLDSTART', 'check': 'Suppress hydraulic filter dP clog alarm during cold start (high oil viscosity inflates dP); enable only after oil reaches operating temperature. Filter dP pop at 4-6 bar must trigger element change, do not reset without replacement', 'severity': 'medium', 'applies_to': 'pressure', 'rationale': 'Cold-start high dP is a known false-alarm source; resetting bypass without change spikes downstream particle count.'}, {'rule_id': 'SURGE_EVENT_COUNT', 'check': 'Count compressor surge cycles in rolling window; alarm at >=1 event, trip at >=3 surges in 10 s', 'severity': 'error', 'applies_to': 'compressor', 'rationale': 'Each surge imposes full pressure reversal; 3-5 events can fatigue-crack impeller blades (Baker Hughes/Bently Nevada).'}, {'rule_id': 'SHAFT_DISP_TRIP_LATENCY', 'check': 'Shaft relative displacement trip (125-160 um) must use digital relay; instability can cross alert-to-trip in under one second', 'severity': 'error', 'applies_to': 'position', 'rationale': 'API 670: turbo-blower can go from alert to 160 um trip in <1 s during instability; analog trip too slow.'}, {'rule_id': 'IMBALANCE_VS_LOOSENESS_PHASE', 'check': 'Distinguish 1x imbalance (stable phase) from looseness (variable phase) before attributing fan vibration to blade erosion', 'severity': 'info', 'applies_to': 'vibration', 'rationale': 'Phase stays constant as amplitude grows for imbalance; variable phase indicates looseness. Mislabeling drives wrong repair.'}, {'rule_id': 'CONVEYOR_MISALIGN_VS_OVERLOAD', 'check': 'Confirm conveyor belt misalignment with thermal camera edge-heat scan to distinguish from generic overload (both raise motor current); belt edge sensor + idler vibration on pull-off side corroborate', 'severity': 'medium', 'applies_to': 'conveyor', 'rationale': 'Motor current rises in both misalignment and overload; thermal scan disambiguates.'}, {'rule_id': 'CRANE_ROPE_MFL_PLUS_DIAMETER', 'check': 'Retire crane wire rope only when MFL defect signal AND diameter reduction together meet ISO 4309 discard criteria', 'severity': 'medium', 'applies_to': 'crane', 'rationale': 'MFL + diameter together are the ISO 4309 discard rule; either alone is insufficient.'}, {'rule_id': 'FURNACE_REFRACTORY_3SENSOR', 'check': 'Distinguish furnace refractory breach from IR-camera noise/soot blockage using IR hot spot + embedded TC zone deviation + flue gas O2/CO2 together', 'severity': 'medium', 'applies_to': 'furnace', 'rationale': 'Three signals needed to separate refractory crack from soot blockage / camera artifact.'}, {'rule_id': 'QR_FLATLINE_STALE', 'check': 'Flag runs of identical values > N samples where N = compression_deadband x scan_rate; cross-correlate with OPC quality codes to classify as [True Steady | Compressed Steady | Stuck Sensor | Communications Loss]. Do NOT assume flat = missing', 'severity': 'high', 'applies_to': 'all', 'rationale': 'Historian swinging-door/exception compression stores a stuck sensor frozen value as Good quality, indistinguishable from true steady or compression flat-line without secondary cross-check. Major ML dataset corruptor.'}, {'rule_id': 'QR_OPC_QUALITY', 'check': 'Reject or flag any sample whose OPC quality field != 192 (Good). Bad=0, Uncertain=64, Good-Clamped=216 (saturated). Treat PI digital states (No Data=248, Shutdown, Bad Input, Configure) as non-numeric gaps', 'severity': 'high', 'applies_to': 'all', 'rationale': 'OPC-DA/UA quality field encodes reliability; upstream PLC comms loss yields Uncertain Last-Usable-Value or Sensor Failure that must not feed control or ML.'}, {'rule_id': 'QR_HARD_RANGE', 'check': 'Flag any value outside the sensor physical hard_min/hard_max as corrupt: drop before anomaly scoring, do not raise a process alarm. Negative pressure/flow = reversed dP or wiring fault; value exactly 0% or 100% of 4-20 mA span = range saturation', 'severity': 'high', 'applies_to': 'all', 'rationale': 'Physically impossible values indicate wiring/transducer faults, not real process behaviour; passing them to models poisons baselines.'}, {'rule_id': 'QR_SPIKE_OUTLIER', 'check': 'Flag value > 6-sigma from rolling mean with duration < 1 scan as spike/impulse outlier (electrical transient, mechanical shock, cable fault); distinguish from genuine impulsive faults via cross-tag correlation', 'severity': 'medium', 'applies_to': 'vibration,pressure', 'rationale': 'Single-scan electrical transients are artifacts; genuine faults persist or co-move across tags.'}, {'rule_id': 'QR_DRIFT', 'check': 'Flag monotonic upward trend over days without corresponding process change as calibration drift / fluid ingress', 'severity': 'medium', 'applies_to': 'temperature,pressure', 'rationale': 'Slow monotonic drift absent process driver indicates calibration shift, not a real fault.'}, {'rule_id': 'QR_MULTIRATE_FORWARDFILL', 'check': 'When joining multi-rate sensors on timestamp, apply forward-fill-with-staleness-limit (carry last temperature up to 5 min; beyond that flag stale). Naive inner-join produces extremely sparse vectors', 'severity': 'high', 'applies_to': 'all', 'rationale': 'A single asset reports vibration 1 Hz, temperature 1/60 Hz, oil 1/600 Hz; inner-join collapses the feature space.'}, {'rule_id': 'QR_GAP_MISSING', 'check': 'Flag NaN/null sequence longer than configurable threshold as missing; classify root cause (comms loss, planned Shutdown state, interface restart, sensor failure). Absence of a row != absence of data (deadband hold)', 'severity': 'medium', 'applies_to': 'all', 'rationale': 'Historian rows appear only on deadband-exceeding change or max-time-interval; gaps need root-cause classification before imputation.'}, {'rule_id': 'QR_TIMESTAMP_INTEGRITY', 'check': 'Detect non-uniform timestamp intervals (jitter from network latency/PLC scan miss), out-of-order or duplicate records (clock skew), UTC-vs-local/DST inconsistencies, PLC clock drift, backdated entries, sub-second precision loss', 'severity': 'medium', 'applies_to': 'all', 'rationale': 'OPC server vs historian clock divergence (no IEEE 1588 PTP) and batch-mode bursts with identical timestamps corrupt time alignment.'}, {'rule_id': 'QR_CALIBRATION_ZERO', 'check': 'Flag persistent offset from known steady-state baseline (calibration zero error from wiring error or drift); flag RTD/transmitter loops with gradual systematic offset (3-10C) for annual recalibration', 'severity': 'medium', 'applies_to': 'temperature,pressure', 'rationale': 'Zero/offset error gives systematically wrong absolute values even when variance looks healthy; RTD drift corrupts baseline and rate-of-change logic.'}, {'rule_id': 'QR_CROSS_SITE_NORMALIZE', 'check': 'Before cross-site model training, normalize via asset UUID + site prefix; reconcile inconsistent unit codes (PSI vs bar vs kPa), variable ISA-95 hierarchy depth, identical tag names across sites, timezone variations', 'severity': 'medium', 'applies_to': 'all', 'rationale': 'Multi-site (Jamshedpur, Kalinganagar, Port Talbot, IJmuiden) tag conventions evolved independently; collisions break cross-site training.'}, {'rule_id': 'QR_CROSS_CORRELATED_ANOMALY', 'check': 'When multiple tags on one asset co-move in deviation, treat as genuine fault signal (true positive), not noise to be filtered', 'severity': 'low', 'applies_to': 'all', 'rationale': 'Correlated multi-tag deviation distinguishes real faults from single-sensor artifacts; must not be suppressed by per-tag outlier rules.'}, {'rule_id': 'QR_PRESSURE_TRANSDUCER_DRIFT', 'check': 'Annual zero/span calibration of pressure transducers (Bourdon-tube fatigue + process vibration cause +/-1-3 bar drift); damp water-hammer spikes with snubbers and flush blocked impulse lines', 'severity': 'medium', 'applies_to': 'pressure', 'rationale': 'Drift and water-hammer false spikes corrupt absolute-pressure fault detection.'}, {'rule_id': 'QR_FLOW_AIR_ENTRAINMENT', 'check': 'Flag electromagnetic/ultrasonic flow spikes consistent with entrained air or coupling loss (pipe scale, poor gel); require upstream straight run and periodic re-coupling', 'severity': 'low', 'applies_to': 'flow', 'rationale': 'Air bubbles spike EM meters; ultrasonic clamp-on coupling loss reads low; both produce nuisance flow alarms.'}, {'rule_id': 'QR_THERMO_PHASE_COMPARE', 'check': 'For electrical-equipment thermography use phase-to-phase dT comparison (not phase-to-ambient) and set correct emissivity (oxidised steel ~0.7-0.85)', 'severity': 'medium', 'applies_to': 'temperature', 'rationale': 'Phase-to-ambient introduces environmental variability; wrong emissivity in radiant steel environment inflates IR readings.'}, {'rule_id': 'QR_SITE_BASELINE_CALIBRATION', 'check': 'All [unverified] thresholds and all AE/ultrasound dB levels are relative to plant-specific baseline; require site baseline calibration before applying absolute alarm thresholds (vary by machine size, speed, fluid grade, installation class)', 'severity': 'high', 'applies_to': 'all', 'rationale': 'Many values are representative estimates needing site calibration; AE/ultrasound are inherently baseline-relative.'}]
